contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _minSum) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);

        uint beforeMinSum = c.MinSum(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.SetMinSum(_minSum); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(reverted && c.MinSum() == beforeMinSum && address(c).balance == beforeBalance);
    }

    receive() external payable {}
}

