// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 _minSum) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 0);
        uint256 beforeMinSum;
        try c.MinSum() returns (uint256 __r) { beforeMinSum = __r; } catch { return; }
        uint beforeBalance = address(c).balance;
        try c.Initialized() {} catch { return; }
        bool reverted;
        try c.SetMinSum(_minSum) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted && c.MinSum() == beforeMinSum && address(c).balance == beforeBalance);
    }

    function testFuzz_run(uint256 _minSum) public {
        _run(_minSum);
    }

    receive() external payable {}
}
